import math

def is_perfect_cube(n):
    if n == 0:
        return True
    # Handle negative numbers by checking the cube root of the absolute value
    sign = 1
    if n < 0:
        sign = -1
        n = -n

    # Estimate the cube root
    root = round(n**(1/3))

    # Check if it's a perfect cube
    return root**3 == n

def calculate_and_check(start, end):
    results = {}
    for x in range(start, end + 1):
        # Calculate P(x) = (8x - 41)(x + 3)^2
        term1 = 8 * x - 41
        term2_sq = (x + 3)**2
        px = term1 * term2_sq

        is_cube = is_perfect_cube(px)
        results[x] = (px, is_cube)
    return results

results = calculate_and_check(-10, 10)

perfect_cubes_x = {}
for x, (px, is_cube) in results.items():
    if is_cube:
        perfect_cubes_x[x] = px

print("Results for x in [-10, 10]:")
for x, (px, is_cube) in results.items():
    print(f"x={x}: P(x) = {px}, Perfect Cube? {is_cube}")

print("\nValues of x for which P(x) is a perfect cube:")
print(perfect_cubes_x)

